class PrimeNumberPrinter {
    boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int divisor = 2;
             divisor * divisor <= number;
             divisor++) {
            if (number % divisor == 0) {
                return false;
            }
        }
        return true;
    }
    void printPrimes() {
        boolean firstPrime = true;

        for (int number = 1; number <= 20; number++) {
            if (isPrime(number)) {
                if (!firstPrime) {
                    System.out.print(" ");
                }

                System.out.print(number);
                firstPrime = false;
            }
        }
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        PrimeNumberPrinter printer = new PrimeNumberPrinter();
        printer.printPrimes();
    }	
}

import java.util.Scanner;
class PrimeRangePrinter {
    boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int divisor = 2;
             divisor * divisor <= number;
             divisor++) {
            if (number % divisor == 0) {
                return false;
            }
        }
        return true;
    }
    void printPrimes(int n) {
        if (n <= 0) {
            System.out.println("Invalid input");
            return;
        }
        boolean primeFound = false;
        for (int number = 2; number <= n; number++) {
            if (isPrime(number)) {
                if (primeFound) {
                    System.out.print(" ");
                }
                System.out.print(number);
                primeFound = true;
            }
        }
        if (primeFound) {
            System.out.println();
        } else {
            System.out.println("No prime numbers");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        PrimeRangePrinter printer = new PrimeRangePrinter();
        printer.printPrimes(n);
        scanner.close();
    }
}

